class DeadlineResolver
  def initialize(date_info, today = Date.today)
    is_one_time_event = date_info.start_with?(/\d{4}-/)
    @due_date = is_one_time_event ? Date.parse(date_info) : Date.parse("#{today.year}-#{date_info}")
    @due_date = @due_date + 365 if !is_one_time_event && (today - @due_date) > 365 / 2
    @today = today
  end

  def is_past_due?
    @due_date < @today
  end

  def remaining_days
    (@due_date - @today).to_i
  end
end

class StatsReporter
  def initialize(cloudwatch_client, environment)
    @client = cloudwatch_client
    @environment = environment
  end

  def report_quarter_hourly
    report_metric('JobsCount', GoodJob::Job.count - GoodJob::Job.succeeded.count)
    report_metric('FailedJobsCount', GoodJob::Job.where.not(error: nil).count)
    report_metric('StuckJobsCount', GoodJob::Job.where(finished_at: nil).where("COALESCE(scheduled_at, created_at) < ?", 1.hour.ago).count)
  end

  private
  def report_metric(name, value)
    @client.put_metric_data(
      namespace: 'NavodyDigital',
      metric_data: [
        {
          metric_name: name,
          dimensions: [{ name: 'Environment', value: @environment }],
          timestamp: Time.current.utc,
          value: value,
        }
      ]
    )
  end
end

